1	import * as THREE from "three";
2	import { BACKGROUND_TRANSITION_CONFIG } from "../config/background.config.js";
3	import { aboutBackground, mainBackground } from "../core/setup.js";
4	import type {
5	  BackgroundLookOptions,
6	  BackgroundObjectOptions,
7	} from "../types/object-visual.types.js";
8	import type {
9	  BackgroundUniformRecord,
10	  BackgroundManagerEntry,
11	  BackgroundManagerRuntimePort,
12	  BackgroundRuntimeState,
13	  BackgroundVariantKey,
14	} from "../types/object-runtime.types.js";
15	import backgroundTransitionFragmentShader from "../../shaders/background/shared/transition.fragment.glsl?raw";
16	import fullscreenVertexShader from "../../shaders/post-processing/additive-blend.vertex.glsl?raw";
17	import { ResponsiveRuntime } from "../runtime/ResponsiveRuntime.js";
18	import { BackgroundMaterialRuntime } from "../runtime/BackgroundMaterialRuntime.js";
19	import { Logger } from "../utils/Logger.js";
20	
21	const BACKGROUND_DEFAULT_LOOK: Required<BackgroundLookOptions> = {
22	  topColor: 0x102f54,
23	  bottomColor: 0x090614,
24	  accentColor: 0x33204b,
25	  starIntensity: 0.78,
26	  starDensity: 0.56,
27	  nebulaStrength: 0.38,
28	  motionStrength: 0.26,
29	  legacyMix: 0,
30	};
31	const ABOUT_VARIANT_ISOLATED_LOOK: Required<BackgroundLookOptions> = {
32	  topColor: 0x101010,
33	  bottomColor: 0x000000,
34	  accentColor: 0x6a6a6a,
35	  starIntensity: 0.08,
36	  starDensity: 0.08,
37	  nebulaStrength: 0.02,
38	  motionStrength: 0.12,
39	  legacyMix: 0,
40	};
41	const BACKGROUND_INITIAL_VARIANT_BY_ID: Readonly<
42	  Partial<Record<string, BackgroundVariantKey>>
43	> = {
44	  [mainBackground]: "intro",
45	  [aboutBackground]: "aboutBase",
46	};
47	const BACKGROUND_KNOWN_VARIANTS = new Set<BackgroundVariantKey>([
48	  "intro",
49	  "introAction",
50	  "aboutBase",
51	  "aboutHeroIntro",
52	  "aboutHeroSlogan",
53	  "aboutWhoIntro",
54	  "aboutMissionVision",
55	  "hero",
56	  "story",
57	  "stars",
58	  "who",
59	  "why",
60	  "services",
61	  "works",
62	  "worksDetail",
63	  "worksFinal",
64	  "client",
65	  "contact",
66	  "footer",
67	]);
68	const BACKGROUND_DEFAULT_RESOLUTION = 1;
69	const BACKGROUND_DEFAULT_EXPOSURE = 0.56;
70	const BACKGROUND_ANCHOR_X = 0.022;
71	const BACKGROUND_ANCHOR_Y = 0.016;
72	const BACKGROUND_ANCHOR_DAMPING = 1.15;
73	const BACKGROUND_STAR_INTENSITY_MIN = 0;
74	const BACKGROUND_STAR_INTENSITY_MAX = 2;
75	const BACKGROUND_STAR_DENSITY_MIN = 0;
76	const BACKGROUND_STAR_DENSITY_MAX = 1;
77	const BACKGROUND_NEBULA_STRENGTH_MIN = 0;
78	const BACKGROUND_NEBULA_STRENGTH_MAX = 1.2;
79	const BACKGROUND_MOTION_STRENGTH_MIN = 0;
80	const BACKGROUND_MOTION_STRENGTH_MAX = 1.2;
81	const BACKGROUND_LEGACY_MIX_MIN = 0;
82	const BACKGROUND_LEGACY_MIX_MAX = 1;
83	const BACKGROUND_HERO_NOISE_TEXTURE_SIZE = 256;
84	const COPY_FRAGMENT_SHADER = `
85	uniform sampler2D uTexture;
86	varying vec2 vUv;
87	
88	void main() {
89	  gl_FragColor = texture2D(uTexture, vUv);
90	}
91	`;
92	
93	export class BackgroundManager implements BackgroundManagerRuntimePort {
94	  private static readonly _CLASS = "BackgroundManager";
95	  private readonly _renderer: THREE.WebGLRenderer;
96	  private readonly _scene: THREE.Scene;
97	  private readonly _camera: THREE.Camera;
98	  private readonly _backgroundScene = new THREE.Scene();
99	  private readonly _backgroundCamera = new THREE.OrthographicCamera(
100	    -1,
101	    1,
102	    1,
103	    -1,
104	    0,
105	    1,
106	  );
107	  private readonly _geometry = new THREE.PlaneGeometry(2, 2);
108	  private readonly _entries = new Map<string, BackgroundManagerEntry>();
109	  private readonly _anchor = new THREE.Vector2(0.5, 0.5);
110	  private readonly _anchorTarget = new THREE.Vector2(0.5, 0.5);
111	  private readonly _cameraEuler = new THREE.Euler(0, 0, 0, "YXZ");
112	  private readonly _displayRenderTarget: THREE.WebGLRenderTarget;
113	  private readonly _variantRenderTarget: THREE.WebGLRenderTarget;
114	  private readonly _transitionFromRenderTarget: THREE.WebGLRenderTarget;
115	  private readonly _mesh: THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial>;
116	  private readonly _copyMaterial: THREE.ShaderMaterial;
117	  private readonly _transitionMaterial: THREE.ShaderMaterial;
118	  private readonly _displacementTexture: THREE.DataTexture;
119	  private readonly _heroNoiseTexture: THREE.DataTexture;
120	  private readonly _materialRuntime: BackgroundMaterialRuntime;
121	  private readonly _initialBackground:
122	    | THREE.Color
123	    | THREE.Texture
124	    | THREE.CubeTexture
125	    | null;
126	  private _elapsedTime = 0;
127	  private _activeEntryId: string | null = null;
128	  private readonly _lookScratch: Required<BackgroundLookOptions> = {
129	    ...BACKGROUND_DEFAULT_LOOK,
130	  };
131	  private _hasRenderedFrame = false;
132	  private _rendererExposureSnapshot: number | null = null;
133	  private _transitionElapsed = 0;
134	  private _transitionActive = false;
135	  private readonly _lastVisibilityById = new Map<string, boolean>();
136	  private _getPerformanceProfile() {
137	    return ResponsiveRuntime.getDefault().getSnapshot().performance;
138	  }
139	
140	  constructor(
141	    renderer: THREE.WebGLRenderer,
142	    scene: THREE.Scene,
143	    camera: THREE.Camera,
144	  ) {
145	    this._renderer = renderer;
146	    this._scene = scene;
147	    this._camera = camera;
148	    this._initialBackground = this._cloneSceneBackground(scene.background);
149	    this._displayRenderTarget = new THREE.WebGLRenderTarget(
150	      BACKGROUND_DEFAULT_RESOLUTION,
151	      BACKGROUND_DEFAULT_RESOLUTION,
152	      {
153	        depthBuffer: false,
154	        stencilBuffer: false,
155	      },
156	    );
157	    this._variantRenderTarget = new THREE.WebGLRenderTarget(
158	      BACKGROUND_DEFAULT_RESOLUTION,
159	      BACKGROUND_DEFAULT_RESOLUTION,
160	      {
161	        depthBuffer: false,
162	        stencilBuffer: false,
163	      },
164	    );
165	    this._transitionFromRenderTarget = new THREE.WebGLRenderTarget(
166	      BACKGROUND_DEFAULT_RESOLUTION,
167	      BACKGROUND_DEFAULT_RESOLUTION,
168	      {
169	        depthBuffer: false,
170	        stencilBuffer: false,
171	      },
172	    );
173	    this._copyMaterial = new THREE.ShaderMaterial({
174	      uniforms: {
175	        uTexture: { value: null },
176	      },
177	      vertexShader: fullscreenVertexShader,
178	      fragmentShader: COPY_FRAGMENT_SHADER,
179	      depthWrite: false,
180	      depthTest: false,
181	      transparent: false,
182	      toneMapped: false,
183	    });
184	    this._transitionMaterial = new THREE.ShaderMaterial({
185	      uniforms: {
186	        time: { value: 0 },
187	        progress: { value: 0 },
188	        width: { value: BACKGROUND_TRANSITION_CONFIG.width },
189	        radius: { value: BACKGROUND_TRANSITION_CONFIG.radius },
190	        displacementIntensity: {
191	          value: BACKGROUND_TRANSITION_CONFIG.displacementIntensity,
192	        },
193	        texture1: { value: this._transitionFromRenderTarget.texture },
194	        texture2: { value: this._variantRenderTarget.texture },
195	        displacement: { value: null },
196	        resolution: { value: new THREE.Vector4(1, 1, 1, 1) },
197	      },
198	      vertexShader: fullscreenVertexShader,
199	      fragmentShader: backgroundTransitionFragmentShader,
200	      depthWrite: false,
201	      depthTest: false,
202	      transparent: false,
203	      toneMapped: false,
204	    });
205	    this._displacementTexture = this._createDisplacementTexture();
206	    this._heroNoiseTexture = this._createNoiseTexture(
207	      BACKGROUND_HERO_NOISE_TEXTURE_SIZE,
208	    );
209	    this._materialRuntime = new BackgroundMaterialRuntime(
210	      () => ({
211	        width: this._displayRenderTarget.width,
212	        height: this._displayRenderTarget.height,
213	      }),
214	      this._heroNoiseTexture,
215	      () => this._getPerformanceProfile().heroRaymarchSteps,
216	    );
217	    (this._transitionMaterial.uniforms.displacement
218	      .value as THREE.DataTexture | null) = this._displacementTexture;
219	    this._mesh = new THREE.Mesh(
220	      this._geometry,
221	      this._materialRuntime.getMaterial("intro"),
222	    );
223	    this._mesh.frustumCulled = false;
224	    this._backgroundScene.add(this._mesh);
225	    this.resize(
226	      renderer.domElement.clientWidth || BACKGROUND_DEFAULT_RESOLUTION,
227	      renderer.domElement.clientHeight || BACKGROUND_DEFAULT_RESOLUTION,
228	      renderer.getPixelRatio(),
229	    );
230	  }
231	
232	  register(
233	    id: string,
234	    options: Partial<BackgroundObjectOptions> = {},
235	    runtimeState: Partial<BackgroundRuntimeState> = {},
236	  ): void {
237	    const current = this._entries.get(id);
238	    if (current) {
239	      this.setOptions(id, options);
240	      this.setRuntimeState(id, runtimeState);
241	      return;
242	    }
243	    this._entries.set(id, {
244	      id,
245	      options: { ...options },
246	      runtimeState: { ...runtimeState },
247	      shaderTimeOffset: this._elapsedTime,
248	    });
249	    this._resolveActiveEntryId();
250	  }
251	
252	  resetShaderClock(id: string): void {
253	    const entry = this._entries.get(id);
254	    if (!entry) return;
255	    entry.shaderTimeOffset = this._elapsedTime;
256	  }
257	
258	  unregister(id: string): void {
259	    this._entries.delete(id);
260	    if (this._activeEntryId !== id) {
261	      this._resolveActiveEntryId();
262	      return;
263	    }
264	    this._activeEntryId = null;
265	    this._resolveActiveEntryId();
266	    if (this._activeEntryId) return;
267	    this._restoreSceneBackground();
268	    this._restoreRendererExposure();
269	  }
270	
271	  setOptions(id: string, options: Partial<BackgroundObjectOptions>): void {
272	    const entry = this._entries.get(id);
273	    if (!entry) return;
274	    const previousVisible = this._isVisible(entry.options);
275	    entry.options = {
276	      ...entry.options,
277	      ...options,
278	      look: this._mergeLook(entry.options.look, options.look),
279	    };
280	    const nextVisible = this._isVisible(entry.options);
281	    if (this._lastVisibilityById.get(id) !== nextVisible) {
282	      this._lastVisibilityById.set(id, nextVisible);
283	      Logger.info(
284	        BackgroundManager._CLASS,
285	        "setOptions",
286	        `Background visibility changed | id: ${id} | visible: ${String(nextVisible)}`,
287	        {
288	          id,
289	          previousVisible,
290	          nextVisible,
291	        },
292	      );
293	    }
294	    this._resolveActiveEntryId();
295	  }
296	
297	  setRuntimeState(id: string, state: Partial<BackgroundRuntimeState>): void {
298	    const entry = this._entries.get(id);
299	    if (!entry) return;
300	    const nextState = {
301	      ...entry.runtimeState,
302	      ...state,
303	    };
304	    if ("look" in state) {
305	      nextState.look = state.look ? { ...state.look } : undefined;
306	    }
307	    if ("shaderControls" in state) {
308	      nextState.shaderControls = state.shaderControls
309	        ? { ...state.shaderControls }
310	        : undefined;
311	    }
312	    entry.runtimeState = nextState;
313	  }
314	
315	  getRuntimeState(id: string): BackgroundRuntimeState {
316	    return { ...(this._entries.get(id)?.runtimeState ?? {}) };
317	  }
318	
319	  hasRenderedFrame(): boolean {
320	    return this._hasRenderedFrame;
321	  }
322	
323	  startTransition(id: string): void {
324	    if (!this._getPerformanceProfile().transitionEnabled) return;
325	    if (!this._entries.has(id) || !this._hasRenderedFrame) return;
326	    this._copyToTarget(
327	      this._displayRenderTarget.texture,
328	      this._transitionFromRenderTarget,
329	    );
330	    this._transitionElapsed = 0;
331	    this._transitionActive = true;
332	  }
333	
334	  update(deltaTime: number): void {
335	    this._elapsedTime += Number.isFinite(deltaTime)
336	      ? Math.max(0, deltaTime)
337	      : 0;
338	    this._updateAnchor(deltaTime);
339	    if (!this._transitionActive) return;
340	    this._transitionElapsed = Math.min(
341	      BACKGROUND_TRANSITION_CONFIG.duration,
342	      this._transitionElapsed + Math.max(0, deltaTime),
343	    );
344	    if (this._transitionElapsed < BACKGROUND_TRANSITION_CONFIG.duration) return;
345	    this._transitionActive = false;
346	  }
347	
348	  render(): void {
349	    const entry = this._getActiveEntry();
350	    if (!entry) {
351	      this._restoreSceneBackground();
352	      this._restoreRendererExposure();
353	      return;
354	    }
355	
356	    const variant = this._resolveVariant(entry);
357	    const material = this._materialRuntime.getMaterial(variant);
358	    this._applyUniforms(material, entry, variant);
359	    this._applyExposure(entry);
360	    this._renderFullscreen(material, this._variantRenderTarget);
361	    if (
362	      this._transitionActive &&
363	      this._getPerformanceProfile().transitionEnabled
364	    ) {
365	      this._renderTransition();
366	    } else {
367	      this._copyToTarget(
368	        this._variantRenderTarget.texture,
369	        this._displayRenderTarget,
370	      );
371	    }
372	    this._hasRenderedFrame = true;
373	    if (this._scene.background !== this._displayRenderTarget.texture) {
374	      this._scene.background = this._displayRenderTarget.texture;
375	    }
376	    this._scene.backgroundIntensity = 1;
377	  }
378	
379	  resize(width: number, height: number, pixelRatio = 1): void {
380	    const performance = this._getPerformanceProfile();
381	    const renderWidth = Math.max(
382	      BACKGROUND_DEFAULT_RESOLUTION,
383	      Math.round(width * pixelRatio * performance.backgroundResolutionScale),
384	    );
385	    const renderHeight = Math.max(
386	      BACKGROUND_DEFAULT_RESOLUTION,
387	      Math.round(height * pixelRatio * performance.backgroundResolutionScale),
388	    );
389	    this._displayRenderTarget.setSize(renderWidth, renderHeight);
390	    this._variantRenderTarget.setSize(renderWidth, renderHeight);
391	    this._transitionFromRenderTarget.setSize(renderWidth, renderHeight);
392	    this._materialRuntime.resize();
393	    const resolution = this._transitionMaterial.uniforms.resolution.value;
394	    if (resolution instanceof THREE.Vector4) {
395	      resolution.set(renderWidth, renderHeight, 1, 1);
396	    }
397	  }
398	
399	  dispose(): void {
400	    this._restoreSceneBackground();
401	    this._restoreRendererExposure();
402	    this._materialRuntime.dispose();
403	    this._geometry.dispose();
404	    this._displayRenderTarget.dispose();
405	    this._variantRenderTarget.dispose();
406	    this._transitionFromRenderTarget.dispose();
407	    this._copyMaterial.dispose();
408	    this._transitionMaterial.dispose();
409	    this._displacementTexture.dispose();
410	    this._heroNoiseTexture.dispose();
411	    this._entries.clear();
412	  }
413	
414	  private _getActiveEntry(): BackgroundManagerEntry | null {
415	    this._resolveActiveEntryId();
416	    if (!this._activeEntryId) return null;
417	    return this._entries.get(this._activeEntryId) ?? null;
418	  }
419	
420	  private _resolveActiveEntryId(): void {
421	    const current = this._activeEntryId
422	      ? this._entries.get(this._activeEntryId)
423	      : null;
424	    if (current && this._isVisible(current.options)) return;
425	    this._activeEntryId = null;
426	    for (const entry of this._entries.values()) {
427	      if (!this._isVisible(entry.options)) continue;
428	      this._activeEntryId = entry.id;
429	      return;
430	    }
431	  }
432	
433	  private _applyUniforms(
434	    material: THREE.ShaderMaterial,
435	    entry: BackgroundManagerEntry,
436	    variant: BackgroundVariantKey,
437	  ): void {
438	    const uniforms = material.uniforms as BackgroundUniformRecord;
439	    const performance = this._getPerformanceProfile();
440	    const look = this._resolveLook(entry, variant);
441	    (uniforms.uTime.value as number) = Math.max(
442	      0,
443	      this._elapsedTime - entry.shaderTimeOffset,
444	    );
445	    (uniforms.uAnchor.value as THREE.Vector2).copy(this._anchor);
446	    (uniforms.uPointer.value as THREE.Vector2).set(0.5, 0.5);
447	    (uniforms.uPointerVelocity.value as THREE.Vector2).set(0, 0);
448	    (uniforms.uPointerStrength.value as number) = 0;
449	    (uniforms.uPointerActive.value as number) = 0;
450	    (uniforms.uTopColor.value as THREE.Color).setHex(look.topColor);
451	    (uniforms.uBottomColor.value as THREE.Color).setHex(look.bottomColor);
452	    (uniforms.uAccentColor.value as THREE.Color).setHex(look.accentColor);
453	    (uniforms.uStarIntensity.value as number) = this._clamp(
454	      look.starIntensity,
455	      BACKGROUND_STAR_INTENSITY_MIN,
456	      BACKGROUND_STAR_INTENSITY_MAX,
457	    );
458	    (uniforms.uStarDensity.value as number) = this._clamp(
459	      look.starDensity,
460	      BACKGROUND_STAR_DENSITY_MIN,
461	      BACKGROUND_STAR_DENSITY_MAX,
462	    );
463	    (uniforms.uNebulaStrength.value as number) = this._clamp(
464	      look.nebulaStrength,
465	      BACKGROUND_NEBULA_STRENGTH_MIN,
466	      BACKGROUND_NEBULA_STRENGTH_MAX,
467	    );
468	    (uniforms.uMotionStrength.value as number) = this._clamp(
469	      look.motionStrength,
470	      BACKGROUND_MOTION_STRENGTH_MIN,
471	      BACKGROUND_MOTION_STRENGTH_MAX,
472	    );
473	    (uniforms.uLegacyMix.value as number) = this._clamp(
474	      look.legacyMix,
475	      BACKGROUND_LEGACY_MIX_MIN,
476	      BACKGROUND_LEGACY_MIX_MAX,
477	    );
478	    (uniforms.uHeroDarken.value as number) = this._clamp(
479	      entry.runtimeState.shaderControls?.heroDarken ?? 0,
480	      0,
481	      1,
482	    );
483	    (uniforms.uStoryDepth.value as number) = this._clamp(
484	      entry.runtimeState.shaderControls?.storyDepth ?? 0,
485	      0,
486	      1,
487	    );
488	    (uniforms.uHeroRaymarchSteps.value as number) =
489	      performance.heroRaymarchSteps;
490	  }
491	
492	  private _resolveLook(
493	    entry: BackgroundManagerEntry,
494	    variant: BackgroundVariantKey,
495	  ): Required<BackgroundLookOptions> {
496	    if (this._isAboutVariant(variant)) {
497	      return this._copyLookInto(ABOUT_VARIANT_ISOLATED_LOOK);
498	    }
499	    const runtimeLook = entry.runtimeState.look;
500	    if (runtimeLook) {
501	      return this._resolveLookFromSource(runtimeLook);
502	    }
503	    return this._resolveLookFromSource(entry.options.look);
504	  }
505	
506	  private _copyLookInto(
507	    source: Required<BackgroundLookOptions>,
508	  ): Required<BackgroundLookOptions> {
509	    const out = this._lookScratch;
510	    out.topColor = source.topColor;
511	    out.bottomColor = source.bottomColor;
512	    out.accentColor = source.accentColor;
513	    out.starIntensity = source.starIntensity;
514	    out.starDensity = source.starDensity;
515	    out.nebulaStrength = source.nebulaStrength;
516	    out.motionStrength = source.motionStrength;
517	    out.legacyMix = source.legacyMix;
518	    return out;
519	  }
520	
521	  private _resolveLookFromSource(
522	    source: BackgroundLookOptions | undefined,
523	  ): Required<BackgroundLookOptions> {
524	    const out = this._lookScratch;
525	    out.topColor = this._resolveFiniteNumber(
526	      source?.topColor,
527	      BACKGROUND_DEFAULT_LOOK.topColor,
528	    );
529	    out.bottomColor = this._resolveFiniteNumber(
530	      source?.bottomColor,
531	      BACKGROUND_DEFAULT_LOOK.bottomColor,
532	    );
533	    out.accentColor = this._resolveFiniteNumber(
534	      source?.accentColor,
535	      BACKGROUND_DEFAULT_LOOK.accentColor,
536	    );
537	    out.starIntensity = this._resolveFiniteNumber(
538	      source?.starIntensity,
539	      BACKGROUND_DEFAULT_LOOK.starIntensity,
540	    );
541	    out.starDensity = this._resolveFiniteNumber(
542	      source?.starDensity,
543	      BACKGROUND_DEFAULT_LOOK.starDensity,
544	    );
545	    out.nebulaStrength = this._resolveFiniteNumber(
546	      source?.nebulaStrength,
547	      BACKGROUND_DEFAULT_LOOK.nebulaStrength,
548	    );
549	    out.motionStrength = this._resolveFiniteNumber(
550	      source?.motionStrength,
551	      BACKGROUND_DEFAULT_LOOK.motionStrength,
552	    );
553	    out.legacyMix = this._resolveFiniteNumber(
554	      source?.legacyMix,
555	      BACKGROUND_DEFAULT_LOOK.legacyMix,
556	    );
557	    return out;
558	  }
559	
560	  private _resolveFiniteNumber(value: unknown, fallback: number): number {
561	    if (typeof value === "number" && Number.isFinite(value)) {
562	      return value;
563	    }
564	    return fallback;
565	  }
566	
567	  private _updateAnchor(deltaTime: number): void {
568	    this._cameraEuler.setFromQuaternion(this._camera.quaternion);
569	    const yaw = THREE.MathUtils.clamp(this._cameraEuler.y, -1, 1);
570	    const pitch = THREE.MathUtils.clamp(this._cameraEuler.x, -0.75, 0.75);
571	    this._anchorTarget.set(
572	      0.5 + yaw * BACKGROUND_ANCHOR_X,
573	      0.5 - pitch * BACKGROUND_ANCHOR_Y,
574	    );
575	    const alpha =
576	      1 - Math.exp(-Math.max(0, deltaTime) * BACKGROUND_ANCHOR_DAMPING);
577	    this._anchor.lerp(this._anchorTarget, alpha);
578	  }
579	
580	  private _applyExposure(entry: BackgroundManagerEntry): void {
581	    const exposure = this._resolveExposure(entry);
582	    if (exposure == null) {
583	      this._restoreRendererExposure();
584	      return;
585	    }
586	    if (this._rendererExposureSnapshot == null) {
587	      this._rendererExposureSnapshot = this._renderer.toneMappingExposure;
588	    }
589	    this._renderer.toneMappingExposure = exposure;
590	  }
591	
592	  private _resolveExposure(entry: BackgroundManagerEntry): number | null {
593	    const runtimeExposure = entry.runtimeState.exposure;
594	    if (
595	      typeof runtimeExposure === "number" &&
596	      Number.isFinite(runtimeExposure)
597	    ) {
598	      return this._clamp(runtimeExposure, 0.05, 2.0);
599	    }
600	    const optionExposure = entry.options.exposure;
601	    if (typeof optionExposure === "number" && Number.isFinite(optionExposure)) {
602	      return this._clamp(optionExposure, 0.05, 2.0);
603	    }
604	    return BACKGROUND_DEFAULT_EXPOSURE;
605	  }
606	
