624	  private _renderTransitionWithProgress(progress: number): void {
625	    (this._transitionMaterial.uniforms.time.value as number) =
626	      this._elapsedTime;
627	    (this._transitionMaterial.uniforms.progress.value as number) = progress;
628	    (this._transitionMaterial.uniforms.texture1.value as THREE.Texture | null) =
629	      this._transitionFromRenderTarget.texture;
630	    (this._transitionMaterial.uniforms.texture2.value as THREE.Texture | null) =
631	      this._variantRenderTarget.texture;
