635	  private _resolveTransitionProgress(): number {
636	    if (!this._transitionActive) return 1;
637	    const normalized = this._clamp(
638	      this._transitionElapsed / BACKGROUND_TRANSITION_CONFIG.duration,
639	      0,
640	      1,
641	    );
642	    return 1 - Math.pow(1 - normalized, 3);
