668	  private _resolveVariant(entry: BackgroundManagerEntry): BackgroundVariantKey {
669	    const variant = entry.runtimeState.variant;
670	    if (variant && BACKGROUND_KNOWN_VARIANTS.has(variant)) {
671	      return variant;
672	    }
