698	  private _createDisplacementTexture(): THREE.DataTexture {
699	    return this._createNoiseTexture(
700	      BACKGROUND_TRANSITION_CONFIG.displacementTextureSize,
701	    );
702	  }
703	
704	  private _createNoiseTexture(size: number): THREE.DataTexture {
705	    const data = new Uint8Array(size * size * 4);
706	    for (let index = 0; index < data.length; index += 4) {
707	      const value = Math.floor(Math.random() * 255);
708	      data[index] = value;
709	      data[index + 1] = value;
710	      data[index + 2] = value;
711	      data[index + 3] = 255;
712	    }
713	    const texture = new THREE.DataTexture(data, size, size, THREE.RGBAFormat);
714	    texture.wrapS = THREE.RepeatWrapping;
715	    texture.wrapT = THREE.RepeatWrapping;
716	    texture.magFilter = THREE.LinearFilter;
717	    texture.minFilter = THREE.LinearFilter;
718	    texture.needsUpdate = true;
719	    return texture;
720	  }
