1247	  private _prepareContactDomMotion(): void {
1248	    const blocks = this._resolveContactRevealBlocks();
1249	    blocks.forEach((block) => {
1250	      block.classList.remove("is-block-reveal-down");
1251	    });
1252	    BlockReveal.prepare(blocks);
1253	    BlockReveal.prepare(this._resolveContactSuccessBlocks());
1254	
1255	    const successTextNodes = this._resolveContactSuccessTextNodes();
1256	    successTextNodes.forEach((node) => {
