1	import * as THREE from "three";
2	import type { AnimationLoopOptions } from "../types/runtime.types.js";
3	import { FrameScheduler } from "../utils/FrameScheduler.js";
4	export { type AnimationLoopOptions } from "../types/runtime.types.js";
5	
6	export const MAX_DELTA_SECONDS = 0.1;
7	
8	const BUDGET_MS = 33;
9	
10	export class AnimationLoop {
11	  private _onUpdate: (deltaTime: number) => void;
12	  private _onRender: () => void;
13	  private _clock: THREE.Clock;
14	  private _id: number | null = null;
15	  private _running = false;
16	  private _frameStart = 0;
17	  private _frameExceeded = false;
18	  private _budgetMs = BUDGET_MS;
19	  private _visibilityListenerAttached = false;
20	  private _resumeOnVisible = false;
21	  private readonly _visibilityHandler = (): void => {
22	    if (typeof document === "undefined") return;
23	    if (document.hidden) {
24	      if (!this._running) return;
25	      this._resumeOnVisible = true;
26	      this.stop();
27	      return;
28	    }
29	    if (!this._resumeOnVisible) return;
30	    this._resumeOnVisible = false;
31	    this.start();
32	  };
33	
34	  get frameExceeded(): boolean {
35	    return this._frameExceeded;
36	  }
37	
38	  private _loop = (): void => {
39	    if (!this._running) return;
40	    this._id = FrameScheduler.request(this._loop);
41	    if (this._frameStart > 0) {
42	      this._frameExceeded =
43	        performance.now() - this._frameStart > this._budgetMs;
44	    }
45	    this._frameStart = performance.now();
46	    const delta = Math.min(this._clock.getDelta(), MAX_DELTA_SECONDS);
47	    this._onUpdate(delta);
48	    this._onRender();
49	  };
50	
51	  constructor(opts: AnimationLoopOptions = {}) {
52	    this._onUpdate = opts.onUpdate ?? (() => {});
53	    this._onRender = opts.onRender ?? (() => {});
54	    if (
55	      Number.isFinite(opts.budgetMs as number) &&
56	      (opts.budgetMs as number) > 0
57	    ) {
58	      this._budgetMs = opts.budgetMs as number;
59	    }
60	    this._clock = new THREE.Clock();
61	  }
62	
63	  start(): void {
64	    if (this._running) return;
65	    if (typeof document !== "undefined" && !this._visibilityListenerAttached) {
66	      document.addEventListener("visibilitychange", this._visibilityHandler);
67	      this._visibilityListenerAttached = true;
68	    }
69	    this._running = true;
70	    this._clock.start();
71	    this._loop();
72	  }
73	
74	  stop(): void {
75	    if (!this._running) return;
76	    this._running = false;
77	    if (this._id != null) {
78	      FrameScheduler.cancel(this._id);
79	      this._id = null;
80	    }
81	    this._clock?.stop();
82	  }
83	
84	  dispose(): void {
85	    this.stop();
86	    if (typeof document !== "undefined" && this._visibilityListenerAttached) {
87	      document.removeEventListener("visibilitychange", this._visibilityHandler);
88	      this._visibilityListenerAttached = false;
89	    }
90	    this._resumeOnVisible = false;
91	  }
92	}
