163	      FEATURE_CARD_CANVAS.listSelector,
164	    );
165	    if (!cardList) return;
166	    const canvasElements = Array.from(
167	      cardList.querySelectorAll<HTMLCanvasElement>(
168	        FEATURE_CARD_CANVAS.canvasSelector,
169	      ),
170	    );
171	    if (canvasElements.length === 0) return;
172	
173	    this._instances = canvasElements.flatMap((canvas, index) => {
174	      const context = canvas.getContext("2d");
175	      if (!context) return [];
176	      return [
177	        {
178	          canvas,
179	          context,
180	          size: { width: 0, height: 0, dpr: 1 },
181	          rotation: index * 0.45,
182	          tilt: 0.6 + index * 0.18,
183	          speed:
184	            FEATURE_CARD_CANVAS.rotationSpeedBase +
185	            index * FEATURE_CARD_CANVAS.rotationSpeedStep,
186	          particles: this._createParticles(index),
187	        },
188	      ];
189	    });
190	
191	    if (this._instances.length === 0) return;
192	
193	    this._resizeListener = () => this._resize();
194	    window.addEventListener("resize", this._resizeListener);
195	    this._resize();
196	    this._startLoop();
197	  }
198	
199	  dispose(): void {
200	    if (this._rafId !== null) {
201	      FrameScheduler.cancel(this._rafId);
202	      this._rafId = null;
203	    }
204	    if (this._resizeListener) {
205	      window.removeEventListener("resize", this._resizeListener);
206	      this._resizeListener = null;
207	    }
208	    this._instances = [];
209	  }
210	
211	  private _startLoop(): void {
212	    const render = (): void => {
213	      this._render();
214	      this._rafId = FrameScheduler.request(render);
215	    };
216	    render();
217	  }
218	
219	  private _resize(): void {
220	    const dpr = Math.min(
221	      ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio,
222	      FEATURE_CARD_CANVAS.pixelRatioMax,
223	    );
224	    this._instances.forEach((instance) => {
225	      const bounds = instance.canvas.getBoundingClientRect();
226	      const width = Math.max(1, Math.round(bounds.width));
227	      const height = Math.max(1, Math.round(bounds.height));
228	      instance.size = { width, height, dpr };
229	      instance.canvas.width = Math.round(width * dpr);
230	      instance.canvas.height = Math.round(height * dpr);
231	      instance.context.setTransform(dpr, 0, 0, dpr, 0, 0);
232	    });
233	  }
234	
235	  private _render(): void {
236	    this._instances.forEach((instance) => {
237	      const { context, size } = instance;
238	      if (size.width <= 0 || size.height <= 0) return;
239	
240	      instance.rotation += instance.speed;
241	      context.clearRect(0, 0, size.width, size.height);
242	      context.fillStyle = FEATURE_CARD_CANVAS.clearColor;
243	      context.fillRect(0, 0, size.width, size.height);
244	
245	      this._drawParticles(instance);
246	      this._drawCube(instance);
247	    });
248	  }
249	
250	  private _drawParticles(instance: FeatureCardCanvasInstance): void {
251	    const { context, size, rotation, particles } = instance;
252	    const halfWidth = size.width * 0.5;
253	    const halfHeight = size.height * 0.5;
254	    const scale =
255	      Math.min(size.width, size.height) * FEATURE_CARD_CANVAS.cubeScale;
256	
257	    context.fillStyle = FEATURE_CARD_CANVAS.particleColor;
258	    particles.forEach((particle) => {
259	      const spin = rotation * (0.6 + particle.drift * 0.4);
260	      const cos = Math.cos(spin);
261	      const sin = Math.sin(spin);
262	      const rotatedX = particle.x * cos - particle.z * sin;
263	      const rotatedZ = particle.x * sin + particle.z * cos;
264	      const depth = rotatedZ + 3.6;
265	      const perspective = 1 / depth;
266	      const drawX = halfWidth + rotatedX * scale * perspective;
267	      const drawY =
268	        halfHeight +
269	        (particle.y + Math.sin(rotation + particle.drift) * 0.14) *
270	          scale *
271	          perspective;
272	      const drawSize = particle.size * perspective * 4.5;
273	      context.fillRect(drawX, drawY, drawSize, drawSize);
274	    });
275	  }
276	
277	  private _drawCube(instance: FeatureCardCanvasInstance): void {
278	    const { context, size, rotation, tilt } = instance;
279	    const halfWidth = size.width * 0.5;
280	    const halfHeight = size.height * 0.5;
281	    const scale =
282	      Math.min(size.width, size.height) * FEATURE_CARD_CANVAS.cubeScale;
283	    const projected = FEATURE_CARD_CUBE_VERTICES.map(([x, y, z]) => {
284	      const rotatedY = this._rotateY(x, z, rotation);
285	      const rotatedX = this._rotateX(y, rotatedY.z, tilt);
286	      const depth = rotatedX.z + 4.2;
287	      const perspective = 1 / depth;
288	      return {
289	        x: halfWidth + rotatedY.x * scale * perspective,
290	        y: halfHeight + rotatedX.y * scale * perspective,
291	      };
292	    });
293	
294	    context.fillStyle = FEATURE_CARD_CANVAS.fillStyle;
295	    context.beginPath();
296	    context.moveTo(projected[4].x, projected[4].y);
297	    context.lineTo(projected[5].x, projected[5].y);
298	    context.lineTo(projected[6].x, projected[6].y);
299	    context.lineTo(projected[7].x, projected[7].y);
300	    context.closePath();
301	    context.fill();
302	
303	    context.strokeStyle = FEATURE_CARD_CANVAS.strokeStyle;
304	    context.lineWidth = 1.2;
305	    FEATURE_CARD_CUBE_EDGES.forEach(([startIndex, endIndex]) => {
306	      const start = projected[startIndex];
307	      const end = projected[endIndex];
308	      context.beginPath();
309	      context.moveTo(start.x, start.y);
310	      context.lineTo(end.x, end.y);
311	      context.stroke();
312	    });
313	  }
314	
315	  private _createParticles(index: number): FeatureCardCanvasParticle[] {
316	    return Array.from(
317	      { length: FEATURE_CARD_CANVAS.particleCount },
318	      (_, particleIndex) => {
319	        const seed = (index + 1) * (particleIndex + 3);
320	        const angle = seed * 0.73;
321	        const radius = 1.2 + (particleIndex % 5) * 0.18;
322	        return {
323	          x: Math.cos(angle) * radius,
324	          y: (((particleIndex % 7) - 3) / 3) * 1.35,
325	          z: Math.sin(angle) * radius,
326	          size:
327	            FEATURE_CARD_CANVAS.particleSizeMin +
328	            (particleIndex % 4) *
329	              ((FEATURE_CARD_CANVAS.particleSizeMax -
330	                FEATURE_CARD_CANVAS.particleSizeMin) /
331	                3),
332	          drift: 0.8 + (particleIndex % 6) * 0.12,
333	        };
334	      },
335	    );
336	  }
337	
338	  private _rotateY(
339	    x: number,
340	    z: number,
341	    angle: number,
342	  ): { x: number; z: number } {
343	    const cos = Math.cos(angle);
344	    const sin = Math.sin(angle);
345	    return {
346	      x: x * cos - z * sin,
347	      z: x * sin + z * cos,
348	    };
349	  }
350	
351	  private _rotateX(
352	    y: number,
353	    z: number,
354	    angle: number,
355	  ): { y: number; z: number } {
356	    const cos = Math.cos(angle);
357	    const sin = Math.sin(angle);
358	    return {
359	      y: y * cos - z * sin,
360	      z: y * sin + z * cos,
361	    };
362	  }
363	}
