365	export class PageRuntime {
366	  private controller: PageController | null = null;
367	  private bootTask: Promise<void> | null = null;
368	  private readonly _globalUiRuntime = new PageGlobalUiRuntime();
369	  private readonly _featureCardCanvasRuntime = new FeatureCardCanvasRuntime();
370	  private readonly _subpageStarfieldRuntime = new SubpageStarfieldRuntime();
371	
372	  async runPage(root?: HTMLElement): Promise<void> {
373	    if (this.bootTask) return this.bootTask;
374	
375	    this.bootTask = (async () => {
376	      this._disposePageRuntime();
377	      this.disposeController();
378	
379	      if ("scrollRestoration" in history) {
380	        history.scrollRestoration = "manual";
381	      }
382	      window.scrollTo({ top: 0, behavior: "auto" });
383	
384	      this._globalUiRuntime.init(root);
385	      this._featureCardCanvasRuntime.init(root);
386	      this._subpageStarfieldRuntime.init(root);
387	
388	      this.controller = new PageController();
389	      await this.controller.init(root);
390	    })().finally(() => {
391	      this.bootTask = null;
392	    });
393	
394	    return this.bootTask;
395	  }
396	
397	  syncAfterContainerChange(): void {
398	    this._globalUiRuntime.syncAfterContainerChange();
399	  }
400	
401	  disposeController(): void {
402	    this.controller?.dispose();
403	    this.controller = null;
404	    this.bootTask = null;
405	    TimelineRuntime.clear();
406	  }
407	
408	  dispose(): void {
409	    this.disposeController();
410	    this._disposePageRuntime();
411	    TimelineRuntime.clear();
412	  }
413	
414	  private _disposePageRuntime(): void {
415	    try {
416	      this._globalUiRuntime.dispose();
417	    } catch (error) {
418	      console.warn(
419	        "[PageRuntime._disposePageRuntime] Global UI cleanup failed.",
420	        error,
421	      );
422	    }
423	    try {
424	      this._featureCardCanvasRuntime.dispose();
425	    } catch (error) {
426	      console.warn(
427	        "[PageRuntime._disposePageRuntime] Feature card canvas cleanup failed.",
428	        error,
429	      );
430	    }
431	    try {
432	      this._subpageStarfieldRuntime.dispose();
433	    } catch (error) {
434	      console.warn(
435	        "[PageRuntime._disposePageRuntime] Subpage starfield cleanup failed.",
436	        error,
437	      );
438	    }
439	  }
440	}
