19	export class AppEngineRuntime {
20	  async init(
21	    options: AppEngineRuntimeInitOptions,
22	  ): Promise<AppEngineRuntimeContext | null> {
23	    ResponsiveRuntime.getDefault().init();
24	    const canvasElement =
25	      options.canvasElement ??
26	      this._resolveCanvasElement(
27	        options.root,
28	        options.pageConfig.three?.canvasId,
29	      );
30	    const engine = this._createEngine(
31	      options.pageConfig,
32	      canvasElement,
33	      options.root ?? null,
34	    );
35	    if (!engine) return null;
36	
37	    const shaderManager = new ShaderManager();
38	    shaderManager.bind(engine);
39	
40	    const shaderController = new ShaderController();
41	    shaderController.bind(engine, shaderManager);
42	
43	    const backgroundController = new BackgroundController();
44	    backgroundController.bind(engine);
45	
46	    const objectSetup = new ObjectSetup();
47	    ObjectFactoryRegistry.registerPageFactories(
48	      objectSetup,
49	      options.pageConfig.pageId,
50	    );
51	
52	    const uiSetup = new UiSetup();
53	    const resizeSetup = new ResizeSetup();
54	
55	    return {
56	      engine,
57	      shaderManager,
58	      shaderController,
59	      backgroundController,
60	      objectSetup,
61	      uiSetup,
62	      resizeSetup,
63	    };
64	  }
65	
66	  dispose(context: AppEngineRuntimeContext | null): void {
67	    if (!context) return;
68	    context.resizeSetup.dispose();
69	    context.uiSetup.dispose();
70	    UI.clearAll();
71	    context.objectSetup.dispose();
72	    context.shaderController.dispose();
73	    context.backgroundController.dispose();
74	    context.shaderManager.dispose();
75	    context.engine.dispose();
76	  }
77	
78	  private _createEngine(
79	    pageConfig: AppEngineRuntimeInitOptions["pageConfig"],
80	    canvasElement: HTMLCanvasElement | null,
81	    root: ParentNode | null,
82	  ): Engine | null {
83	    const three = pageConfig.three;
84	    if (!three) return null;
85	    const responsive = ResponsiveRuntime.getDefault().getSnapshot();
86	
87	    const engine = new Engine({
88	      canvasId: three.canvasId,
89	      canvasElement,
90	      camera: three.camera,
91	      cameraTarget: three.cameraTarget,
92	      renderer: {
93	        ...three.renderer,
94	        antialias: responsive.performance.rendererAntialias,
95	        powerPreference: responsive.performance.rendererPowerPreference,
96	      },
97	      pixelRatioMax: Math.min(
98	        three.pixelRatioMax,
99	        responsive.render.pixelRatioMax,
100	      ),
101	      shadowMap: three.shadowMap,
102	      renderBudget: this._resolveRenderBudget(
103	        three.renderBudget,
104	        responsive.performance,
105	      ),
106	      scene: three.scene,
107	      postProcessing: this._resolvePostProcessing(
108	        three.postProcessing,
109	        responsive.performance,
110	      ),
111	    });
112	
113	    if (!engine.init()) {
114	      this._applyDomRendererFallback(canvasElement, root, three.canvasId);
115	      return null;
116	    }
117	
118	    engine.applyResponsiveSnapshot(responsive);
119	    return engine;
120	  }
121	
122	  private _resolveCanvasElement(
123	    root: ParentNode | null | undefined,
124	    canvasId: string | undefined,
125	  ): HTMLCanvasElement | null {
126	    if (!canvasId) return null;
127	    if (!root) {
128	      return document.getElementById(canvasId) as HTMLCanvasElement | null;
129	    }
130	    if (root instanceof HTMLCanvasElement && root.id === canvasId) {
131	      return root;
132	    }
133	    return root.querySelector<HTMLCanvasElement>(`#${canvasId}`);
134	  }
135	
136	  private _applyDomRendererFallback(
137	    canvasElement: HTMLCanvasElement | null,
138	    root: ParentNode | null,
139	    canvasId: string | undefined,
140	  ): void {
141	    if (typeof document === "undefined") return;
142	    const target = this._resolveFallbackTarget(canvasElement, root, canvasId);
143	    if (!(target instanceof HTMLElement)) return;
144	    target.style.background = APP_MANAGER_DOM.rendererFallbackBackground;
145	  }
146	
147	  private _resolveFallbackTarget(
148	    canvasElement: HTMLCanvasElement | null,
149	    root: ParentNode | null,
150	    canvasId: string | undefined,
151	  ): HTMLElement | null {
152	    if (canvasElement?.parentElement) return canvasElement.parentElement;
153	    if (root instanceof HTMLElement) return root;
154	    if (root) {
155	      const scopedHost = canvasId
156	        ? root.querySelector<HTMLElement>(`#${canvasId}`)
157	        : null;
158	      if (scopedHost) return scopedHost;
159	    }
160	    if (!canvasId) return document.body;
161	    const globalHost = document.getElementById(canvasId);
162	    if (globalHost instanceof HTMLElement) return globalHost;
163	    return document.body;
164	  }
165	
166	  private _resolveRenderBudget(
167	    renderBudget: RenderBudgetOptions | undefined,
168	    performance: MainPerformanceProfile,
169	  ): RenderBudgetOptions | undefined {
170	    if (!renderBudget) return undefined;
171	    if (performance.tier !== "low") return renderBudget;
172	    return {
173	      ...renderBudget,
174	      mode: "performance",
175	    };
176	  }
177	
178	  private _resolvePostProcessing(
179	    postProcessing: PostProcessorOptions | undefined,
180	    performance: MainPerformanceProfile,
181	  ): PostProcessorOptions | undefined {
182	    if (!postProcessing) return undefined;
183	    if (postProcessing.bloom === false) return postProcessing;
184	
185	    const bloom =
186	      typeof postProcessing.bloom === "object" && postProcessing.bloom != null
187	        ? { ...performance.bloom, ...postProcessing.bloom }
188	        : { ...performance.bloom };
189	
190	    return {
191	      ...postProcessing,
192	      bloom,
193	    };
194	  }
195	}
