7	export class AppStartupRuntime {
8	  async start(
9	    options: AppStartupRuntimeOptions,
10	  ): Promise<AppStartupRuntimeResult> {
11	    const {
12	      engine,
13	      engineContext,
14	      pageConfig,
15	      objectSetupPromise,
16	      onBootStateApply,
17	      pageBootRuntime,
18	      onOrbitSetup,
19	      onShaderUpdate,
20	      onOrbitUpdate,
21	      onScrollSyncStart,
22	    } = options;
23	
24	    await objectSetupPromise;
25	    this._applySceneState(engine, pageConfig);
26	    await onBootStateApply?.();
27	    await pageBootRuntime.apply(engine, pageConfig.pageId);
28	    engineContext.uiSetup.init(engine);
29	    await onOrbitSetup();
30	
31	    engine.start(
32	      (deltaTime: number) => {
33	        engineContext.uiSetup.update(deltaTime);
34	        onShaderUpdate(deltaTime);
35	      },
36	      () => {
37	        onOrbitUpdate();
38	      },
39	    );
40	    engineContext.resizeSetup.init(engine);
41	    onScrollSyncStart?.();
42	
43	    return {
44	      debugPanelDispose: attachDebug(engine) ?? null,
45	    };
46	  }
47	
48	  private _applySceneState(
49	    engine: AppStartupRuntimeOptions["engine"],
50	    pageConfig: AppStartupRuntimeOptions["pageConfig"],
51	  ): void {
52	    const three = pageConfig.three;
53	    const initialState = pageConfig.initialState;
54	    const effectiveState: Record<string, unknown> = initialState
55	      ? { ...initialState }
56	      : {
57	          camera: three?.camera,
58	          cameraTarget: three?.cameraTarget,
59	        };
60	    if (Object.keys(effectiveState).length === 0) return;
61	    engine.setState(effectiveState);
62	  }
63	}
