142	  private shouldPreventLenis(node: Element): boolean {
143	    if (!(node instanceof Element)) return false;
144	    if (node.closest(LENIS_PREVENT_SELECTORS) != null) return true;
145	    const rootNode = node.getRootNode();
146	    if (!(rootNode instanceof ShadowRoot)) return false;
